 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'Cà Mau',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; hoạt động bán lẻ chưa xác minh thực địa. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-ca-mau-old-wave-02'
 FROM src s WHERE s.district IN ('Huyện Trần Văn Thời','Huyện Cái Nước','Huyện Đầm Dơi') AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM customers c WHERE c.province='Cà Mau' AND c.district=s.district AND
 (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM field_prospects p WHERE p.province='Cà Mau' AND p.district=s.district AND
 (p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone)
